// Isolated, self-contained publish sub-chain for reconciliation -- does not
// share nodes with the create-path publish chain, so this can never regress
// the already-working create flow. Runs once per input item -- multiple
// unpublished products can be in flight at once.
const producers = $('🩺 Build GraphQL: Get Publication (Reconcile)').all();
return $input.all().map((item, i) => {
  const res = item.json;
  if (res?.errors?.length) {
    throw new Error('Shopify GraphQL error (get publications, reconcile): ' + JSON.stringify(res.errors));
  }
  const pubs = res?.data?.publications?.nodes || [];
  const onlineStore = pubs.find(p => p.name === 'Online Store');
  if (!onlineStore) {
    throw new Error('Could not find an "Online Store" publication/sales channel on this shop: ' + JSON.stringify(pubs));
  }

  const productLegacyId = producers[i]?.json?.product_legacy_id;
  if (!productLegacyId) {
    throw new Error('Reconcile publish: missing product id for item ' + i);
  }

  const QUERY = `mutation PublishProduct($id: ID!, $input: [PublicationInput!]!) {
  publishablePublish(id: $id, input: $input) {
    publishable { ... on Product { id } }
    userErrors { field message }
  }
}`;

  return {
    json: {
      body: {
        query: QUERY,
        variables: {
          id: `gid://shopify/Product/${productLegacyId}`,
          input: [{ publicationId: onlineStore.id }]
        }
      }
    }
  };
});

return $input.all().map(item => ({
  json: {
    product_legacy_id: item.json?.data?.product?.legacyResourceId,
    body: { query: `query GetOnlineStorePublication { publications(first: 10) { nodes { id name } } }` }
  }
}));

return $input.all().map(item => ({
  json: {
    body: {
      query: `query CheckPublication($id: ID!) { product(id: $id) { legacyResourceId onlineStoreUrl } }`,
      variables: { id: `gid://shopify/Product/${item.json.product_id}` }
    }
  }
}));

const sheetName = $("\ud83d\udd04 Loop Through Sheets").item?.json?.sheet_name
  ?? $("\ud83d\udd04 Loop Through Sheets").first()?.json?.sheet_name;
const rows = $input.all().map(i => i.json);

// Shopify's CDN appends a `v=` cache-busting query param that changes on every
// fetch/serve without indicating a different file -- confirmed directly via
// curl: two URLs differing only in `v=` return identical content-length and
// Shopify's own `Link: rel="canonical"` response header, which strips `v=`
// and points BOTH at the exact same canonical URL. Stripped only for
// duplicate-comparison purposes -- the original src (with its real v=) is
// still what gets written/uploaded. This is not a fuzzy filename/suffix
// match (still forbidden) -- it's a verified-equivalent query param on an
// otherwise byte-identical URL.
// Pure string manipulation -- deliberately avoids the `URL`/`URLSearchParams`
// globals, which are not guaranteed to exist in every Code-node execution
// sandbox (confirmed the hard way: an earlier version used `new URL()` and
// silently no-op'd via its own try/catch in production, with zero visible
// error, because that global wasn't available there).
const normalizeImageUrl = (url) => {
  const str = String(url || '');
  const qIndex = str.indexOf('?');
  if (qIndex === -1) return str;
  const base = str.slice(0, qIndex);
  const keptParams = str.slice(qIndex + 1)
    .split('&')
    .filter(pair => pair && !/^v=/.test(pair))
    .join('&');
  return keptParams ? `${base}?${keptParams}` : base;
};

// Writing IMAGE URL11 alone is silent to the main sync pipeline -- it only
// ever pushes an already-published product's image/metafield changes to
// Shopify when Fields_to_update names the exact changed field ("IMAGE URL11"
// for the gallery slot, "CAD Drawing URL" for the "Download CAD Drawing"
// button metafield -- two separate downstream consumers of this same sheet
// value). Without flagging both here, a CAD drawing added or changed on a
// product that's already live on Shopify sits correctly in the sheet but
// never reaches the website. Only applies to already-published rows (has
// both Shopify_Product_URL and Shopify_Update_product_URL) -- a row still
// pending its first creation doesn't need this, and setting Fields_to_update
// on it would incorrectly flip it out of the plain "create" classification.
function hasValue(v) { return v !== undefined && v !== null && String(v).trim() !== ''; }
// Always returns defined Fields_to_update/Ready_to_post values -- the write
// node below maps these columns on every row, so leaving either undefined
// here would write blank and silently wipe out any OTHER pending flag (or
// the row's actual Ready_to_post state) already sitting in that cell.
// When nothing needs flagging, both echo the row's current values unchanged.
//
// Ready_to_post is set to 'yes' whenever a new token gets added -- Fields_to
// update alone is inert: "\u2705 Filter Unacknowledged & Ready to Post"'s
// getOperationType() short-circuits to null (row skipped entirely) unless
// Ready_to_post is also 'yes'. Without this, a row whose CAD Drawing URL
// changes on an already-published product gets correctly flagged here but
// then sits stuck forever -- confirmed live on LSBLD496/497, published rows
// with Fields_to_update populated and Ready_to_post never touched.
function withCadTokensFlagged(row) {
  // NO LONGER flags anything. This used to add IMAGE URL11 / CAD Drawing URL to Fields_to_update and set
  // Ready_to_post to 'yes' on every already-published row whose CAD differed from IMAGE URL11 -- an
  // automatic trigger for product updates that nobody asked for (thousands of rows at once). Now the
  // sync only mirrors the sheet's own IMAGE URL11 cell and echoes the row's current flags unchanged,
  // so a product already on Shopify is only updated when a person flags the row.
  return { 'Fields_to_update': String(row['Fields_to_update'] || ''), 'Ready_to_post': String(row['Ready_to_post'] || '') };
}

const out = [];
for (const row of rows) {
  const cad = String(row['CAD Drawing URL'] || '').trim();
  const current = String(row['IMAGE URL11'] || '').trim();

  // CAD Drawing URL was removed entirely (not replaced by a duplicate --
  // that case is handled below) -- IMAGE URL11 exists solely to mirror this
  // column, so it must be cleared too instead of left pointing at a CAD
  // drawing that no longer exists in the sheet. Only acts if URL11 actually
  // has something to clear.
  if (!cad) {
    if (current) out.push({ json: { row_number: row.row_number, sheet_name: sheetName, 'IMAGE URL11': '', ...withCadTokensFlagged(row) } });
    continue;
  }

  // IMAGE URL11 always mirrors CAD Drawing URL unconditionally -- it is NOT
  // suppressed when the CAD file happens to be an exact duplicate of one of
  // this product's other photos (IMAGE URL1-10). Uploading the same file
  // twice is already prevented one layer downstream: extractImages()
  // (in "\u2705 Filter Unacknowledged & Ready to Post") dedupes the final
  // Shopify image list across ALL 11 IMAGE URL columns by exact URL (after
  // the same v=-cache-buster-insensitive normalization used here), so a
  // duplicate CAD URL never becomes a second upload -- it just means the
  // photo already visible in the gallery is the one the CAD button also
  // points to, which is the correct, honest reflection of the sheet data.
  const cadNorm = normalizeImageUrl(cad);
  if (normalizeImageUrl(current) === cadNorm) continue; // already in sync (v= cache-buster ignored)
  out.push({ json: { row_number: row.row_number, sheet_name: sheetName, 'IMAGE URL11': cad, ...withCadTokensFlagged(row) } });
}
return out;

// ============================================
// CONFIGURATION
// ============================================
const CONFIG = {
  MAX_CREATE_ITEMS: 3,
  VENDOR: 'Marblebee',
  WEIGHT_UNIT: 'kg',
  DECIMAL_PLACES: 2,

  // LOCK SWITCH: when false, products that already exist on Shopify are never changed by this sync.
  // Currently TRUE (updates allowed) -- set to false to stop all updates to published products if needed.
  // Only CREATE (new products) goes through. Turn it on (true) only for a run where someone has
  // deliberately flagged rows for update, then turn it off again.
  ALLOW_UPDATES_TO_PUBLISHED: true,

  IMAGE_KEYS: [
    'IMAGE URL1',
    'IMAGE URL2',
    'IMAGE URL3',
    'IMAGE URL4',
    'IMAGE URL5',
    'IMAGE URL6',
    'IMAGE URL7',
    'IMAGE URL8',
    'IMAGE URL9',
    'IMAGE URL10',
    'IMAGE URL11'
  ],

  SHEET_NAME: $input.first()?.json?.__sheet_name ?? $('🔄 Loop Through Sheets').item.json.sheet_name
};

// ============================================
// UTILITIES
// ============================================

const safeRound = (value, decimals = CONFIG.DECIMAL_PLACES) => {
  const num = parseFloat(value);
  return Number.isFinite(num)
    ? Number(num.toFixed(decimals))
    : '';
};

const cleanWeight = (weightRaw) => {
  const cleaned = String(weightRaw ?? '0').replace(/[^\d.]/g, '');
  return cleaned ? parseFloat(cleaned) : 0.0;
};

const safeNumeric = (value, defaultValue = 0) => {
  const num = parseFloat(value);
  return Number.isFinite(num)
    ? num
    : defaultValue;
};

// Sheet price -> number, or null when it is blank / not a number / zero or negative.
// Tolerates "$1,285.00", "1,285", "USD 625". A null price must NEVER be turned into 0:
// a product created with a 0 price is orderable for free (LSLT046-054 went live at $0.00
// and order #1567 was placed for $0).
const parsePrice = (value) => {
  const cleaned = String(value ?? '').replace(/[^0-9.\-]/g, '');
  const num = parseFloat(cleaned);
  return Number.isFinite(num) && num > 0 ? num : null;
};

const hasValidPrice = (data) => parsePrice(data?.['Price IN USD $ (Jack)']) !== null;

const hasValue = (value) =>
  value !== undefined &&
  value !== null &&
  String(value).trim() !== '';


// ============================================
// SEO HELPERS
// ============================================

// Shopify handle formatter
const slugify = (text = '') =>
  String(text)
    .toLowerCase()
    .trim()
    .replace(/&/g, 'and')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');


// URL HANDLE RULE:
// "{keyword}-{material}-{product-number}"
const buildHandle = (data) => {
  const keyword = data['Keywords (Luna)'] ?? '';
  const material = data.Material ?? '';
  const productNumber = String(data['Product No.'] ?? '').trim();

  // Product No. is the primary disambiguator for the handle -- without it, two
  // rows sharing the same keyword+material (common for a generic category like
  // "Stone Mosaic" + "Marble") slugify to the identical handle and Shopify
  // rejects the create with HANDLE_NOT_UNIQUE. Fall back to this row's own
  // sheet+row_number (already guaranteed unique) so a missing Product No. can
  // never cause a handle collision.
  const disambiguator = productNumber || `${CONFIG.SHEET_NAME}-row${data.row_number ?? ''}`;

  return slugify(
    `${keyword}-${material}-${disambiguator}`
  );
};


// IMAGE ALT RULE:
// "{keyword} in {material} - Image {index}"
const buildAltText = (data, index) => {
  const keyword = (data['Keywords (Luna)'] ?? 'Marble Product').trim();
  const material = (data.Material ?? 'Natural Marble').trim();

  return `${keyword} in ${material} - Image ${index}`;
};


// Shopify's CDN appends a `v=` cache-busting query param that changes on every
// fetch/serve without indicating a different file -- confirmed directly via
// curl: two URLs differing only in `v=` return identical content-length and
// Shopify's own `Link: rel="canonical"` response header, which strips `v=`
// and points BOTH at the exact same canonical URL. So `v=` is stripped only
// for the purposes of comparing "is this the same image" -- it is NOT a fuzzy
// filename/suffix match (still forbidden -- see extractImages below), it is a
// verified-equivalent query param on an otherwise byte-identical URL.
// Pure string manipulation -- deliberately avoids the `URL`/`URLSearchParams`
// globals, which are not guaranteed to exist in every Code-node execution
// sandbox (confirmed the hard way: an earlier version used `new URL()` and
// silently no-op'd via its own try/catch in production, with zero visible
// error, because that global wasn't available there).
const normalizeImageUrl = (url) => {
  const str = String(url || '');
  const qIndex = str.indexOf('?');
  if (qIndex === -1) return str;
  const base = str.slice(0, qIndex);
  const keptParams = str.slice(qIndex + 1)
    .split('&')
    .filter(pair => pair && !/^v=/.test(pair))
    .join('&');
  return keptParams ? `${base}?${keptParams}` : base;
};

// Build Shopify images with alt text -- any IMAGE URL slot whose value is an
// EXACT duplicate of an earlier slot's URL (after stripping Shopify's `v=`
// cache-buster, see normalizeImageUrl above) is skipped so the same photo is
// never uploaded to Shopify twice. Filenames can legitimately be similar
// (e.g. "-2.jpg" / "-2_1.jpg" / "-2_2.jpg" as genuinely different photos from
// the same shoot) so no other normalization is applied -- never a fuzzy
// filename/suffix match.
const extractImages = (data, keys) => {
  const seenUrls = new Set();
  const images = [];
  keys.forEach((key, idx) => {
    if (!hasValue(data[key])) return;
    const src = String(data[key]).trim();
    const normalized = normalizeImageUrl(src);
    if (seenUrls.has(normalized)) return;
    seenUrls.add(normalized);
    // Slot number is the image's fixed position in CONFIG.IMAGE_KEYS (IMAGE
    // URL1 -> 1, ..., IMAGE URL11 -> 11) -- NOT a running count of images seen
    // so far. A running count silently renumbers every later slot whenever an
    // earlier one is added, removed, or deduped (e.g. the IMAGE URL11 CAD sync
    // toggling on and off) -- and that renumbering broke the Shopify-side
    // alt-text identity match used to correlate "this is the same photo" on
    // every subsequent update, causing real photos to be deleted as
    // "orphans" and silently replaced with dead sheet links.
    images.push({ src, alt: buildAltText(data, idx + 1) });
  });
  return images;
};


// ============================================
// VALIDATION & OPERATION TYPE
// ============================================

const isReadyToPost = (data) => {
  const value = String(data?.Ready_to_post ?? '')
    .trim()
    .toLowerCase();

  return value === 'yes' || value === 'true';
};

const hasTitle = (data) =>
  hasValue(data?.Title_Shopify);

const getOperationType = (data) => {

  if (!isReadyToPost(data) || !hasTitle(data)) {
    return null;
  }

  const hasFieldsToUpdate = hasValue(data.Fields_to_update);
  const hasPublicUrl = hasValue(data.Shopify_Product_URL);
  const hasAdminUrl = hasValue(data.Shopify_Update_product_URL);

  // UPDATE
  if (
    hasFieldsToUpdate &&
    hasPublicUrl &&
    hasAdminUrl
  ) {
    // Locked by default: the row is left exactly as it is (no Shopify call, no sheet write).
    return CONFIG.ALLOW_UPDATES_TO_PUBLISHED ? 'update' : null;
  }

  // CREATE
  if (
    !hasFieldsToUpdate &&
    !hasPublicUrl &&
    !hasAdminUrl
  ) {
    // No valid price -> do NOT create the product. 'mark false' sets Ready_to_post back to
    // "no" on the row (the existing path), so nothing is posted and the row visibly drops out
    // of the ready list until someone fills in the price and ticks it again.
    return hasValidPrice(data) ? 'create' : 'mark false';
  }

  return 'mark false';
};


// ============================================
// PRODUCT BUILDER
// ============================================

const buildProduct = (data, operation) => {

  const weight = safeRound(
    cleanWeight(data['Weight KG'])
  );

  // null when blank / invalid / <= 0 (see parsePrice). Create rows never get here without a
  // valid price; for updates a null price is simply left out, so an existing price is never
  // overwritten with 0.
  const price = parsePrice(
    data['Price IN USD $ (Jack)']
  );

  // ============================================
  // DIMENSIONS
  // ============================================

  const isFireplace =
    CONFIG.SHEET_NAME === 'Fireplace'  ||
    CONFIG.SHEET_NAME === 'Test data';

  const isCarving =
    CONFIG.SHEET_NAME === 'Carving';

  const isWindowSurround =
    CONFIG.SHEET_NAME === 'WindowSurround';

  const isWallCoverings =
    CONFIG.SHEET_NAME === 'Wall-Coverings'

  const isExteriorWallDecoration =
    CONFIG.SHEET_NAME === 'Exterior-Wall-Decoration'

  const isMarbleSlab =
    CONFIG.SHEET_NAME === 'MarbleSlab';

  const isMarbleRangeHood =
    CONFIG.SHEET_NAME === 'MarbleRangeHood';

  const isMoulding =
    CONFIG.SHEET_NAME === 'Moulding';

  const isStoneMosaicTile =
    CONFIG.SHEET_NAME === 'StoneMosaicTile';

  const isMarbleMedallion =
    CONFIG.SHEET_NAME === 'MarbleMedallion';

  const isWainscoting =
    CONFIG.SHEET_NAME === 'Wainscoting';

  const isOutdoorCornice =
    CONFIG.SHEET_NAME === 'OutdoorCornice';

  const isBookMatchedSlabs =
    CONFIG.SHEET_NAME === 'BookMatchedSlabs';

  const isStairs =
    CONFIG.SHEET_NAME === 'Stairs';

  const isBalustrade =
    CONFIG.SHEET_NAME === 'Balustrade';

  const dimensions = isMarbleSlab || isWallCoverings || isStoneMosaicTile || isMarbleMedallion || isExteriorWallDecoration || isWainscoting
    ? {
        l_cm: data['Length CM'] ?? '',
        w_cm: data['Width CM'] ?? '',
        t_cm: data['Thickness CM'] ?? '',

        l_in: safeRound(data['Length Inch']) ?? '',
        w_in: safeRound(data['Width Inch']),
        t_in: safeRound(data['Thickness Inch'])
      }
    : isFireplace || isMarbleRangeHood || isCarving || isWindowSurround 
    ? {
        d_cm: data['Depth CM'] ?? '',
        w_cm: data['Width CM'] ?? '',
        h_cm: data['Height CM'] ?? '',

        d_in: safeRound(data['Depth Inch']) ?? '',
        w_in: safeRound(data['Width Inch']),
        h_in: safeRound(data['Height Inch'])
      }
    : isMoulding
    ? {
        l_cm: data['Length CM'] ?? '',
        h_cm: data['Height CM'] ?? '',
        t_cm: data['Thickness CM'] ?? '',

        l_in: safeRound(data['Length Inch']) ?? '',
        h_in: safeRound(data['Height Inch']),
        t_in: safeRound(data['Thickness Inch'])
      }
    : isOutdoorCornice
    ? {
        l_cm: data['Length CM'] ?? '',
        h_cm: data['Height CM'] ?? '',
        p_cm: data['Projection CM'] ?? '',

        l_in: safeRound(data['Length Inch']) ?? '',
        h_in: safeRound(data['Height Inch']),
        p_in: safeRound(data['Projection Inch'])
      }
    : isStairs
    ? {
        w_cm: data['Width CM'] ?? '',
        h_cm: data['Height CM'] ?? '',
        diam_cm: data['Diameter CM'] ?? '',
        io_diam_cm: data['Inner Opening Diameter CM'] ?? '',

        w_in: safeRound(data['Width Inch']) ?? '',
        h_in: safeRound(data['Height Inch']),
        diam_in: safeRound(data['Diameter Inch']) ?? '',
        io_diam_in: safeRound(data['Inner Opening Diameter Inch']) ?? '',
      }
    : isBalustrade
    ? {
        oh_cm: data['Overall Height CM'] ?? '',
        hh_cm: data['Handrail Height CM'] ?? '',
        hw_cm: data['Handrail Width CM'] ?? '',
        bd_cm: data['Baluster Diameter CM'] ?? '',
        bh_cm: data['Baluster Height CM'] ?? '',
        bpw_cm: data['Base/Plinth Width CM'] ?? '',
        bph_cm: data['Base/Plinth Height CM'] ?? '',

        oh_in: safeRound(data['Overall Height Inch']) ?? '',
        hh_in: safeRound(data['Handrail Height Inch']) ?? '',
        hw_in: safeRound(data['Handrail Width Inch']) ?? '',
        bd_in: safeRound(data['Baluster Diameter Inch']) ?? '',
        bh_in: safeRound(data['Baluster Height Inch']) ?? '',
        bpw_in: safeRound(data['Base/Plinth Width Inch']) ?? '',
        bph_in: safeRound(data['Base/Plinth Height Inch']) ?? '',
      }
    : isBookMatchedSlabs
    ? {
        l_cm: data['Length CM'] ?? '',
        w_cm: data['Width CM'] ?? '',

        l_in: safeRound(data['Length Inch']) ?? '',
        w_in: safeRound(data['Width Inch']),
      }
    : {
        l_cm: data['Length CM'] ?? '',
        w_cm: data['Width CM'] ?? '',
        h_cm: data['Height CM'] ?? '',

        l_in: safeRound(data['Length Inch']) ?? '',
        w_in: safeRound(data['Width Inch']),
        h_in: safeRound(data['Height Inch'])
      };

  // ============================================
  // Opening Size For Fireplace
  // ============================================

  const opening_size = isFireplace
    ? {
        opening_w_cm: data['Width_CM'] ?? '',
        opening_h_cm: data['Height_CM'] ?? '',

        opening_w_in: safeRound(data['Width_Inch']),
        opening_h_in: safeRound(data['Height_Inch'])
      }
    : {}

  // ============================================
  // SEO
  // ============================================

  const seoTitle =
    String(data.Shopify_SEO_Title || data.Title_Shopify || '').trim();

  const seoDescription =
    String(data.Shopify_SEO_Description ?? '').trim();

  const handle = buildHandle(data);

  // ============================================
  // RETURN PRODUCT
  // ============================================

  return {

    // Metadata
    row_number: data.row_number ?? 0,
    sheet_name: CONFIG.SHEET_NAME ?? '',
    updating_fields: data.Fields_to_update ?? '',
    operation,

    // URLs
    public_shopify_url:
      data.Shopify_Product_URL ?? '',

    admin_shopify_url:
      data.Shopify_Update_product_URL ?? '',

    // Dimensions
    ...dimensions,
    ...opening_size,

    // Shopify Product
    title: String(data.Title_Shopify ?? '').trim(),
    description: String(data.Description_Shopify ?? '').trim(),

    material: String(data.Material ?? '').trim(),
    product_number: String(data['Product No.'] ?? '').trim(),

    weight,

    drain_diameter:
      data.Drain_Diameter ?? '',

    radius: data.Radius ?? '',
    surface: data.Surface ?? '',

    signature:
      data.Signature ?? '',

    // SEO

    seo_title: seoTitle,
    seo_description: seoDescription,
    handle,

    // Custom buttons
    material_catalog_url:
      String(data['Material Catalog URL'] ?? '').trim(),

    care_guide_url:
      String(data['Care Guide URL'] ?? '').trim(),

    cad_drawing_url:
      String(data['CAD Drawing URL'] ?? '').trim(),

    price_unit_suffix: (isExteriorWallDecoration || isMoulding || isOutdoorCornice || isStoneMosaicTile || isWallCoverings) ? '/piece' : isBalustrade ? '/linear ft' : '',

    // Etsy
    title_Etsy:
      data.Title_Etsy ?? '',

    description_Etsy:
      data.Description_Etsy ?? '',

    tags_Etsy:
      data.Tags_Etsy ?? '',

    who_made:
      data.who_made ?? '',

    when_made:
      data.when_made ?? '',

    product_type_Etsy:
      data.Etsy_type ?? '',

    quantity_Etsy:
      data.Etsy_quantity ?? 0,

    // Shopify
    vendor: CONFIG.VENDOR,

    product_type:
      String(data.Product_Type ?? 'Default').trim(),

    tags:
      String(data.Tags_Shopify ?? '').trim(),

    // Variants
    variants: [
      {
        requires_shipping: false,
        ...(price !== null ? { price } : {}),
        weight,
        weight_unit: CONFIG.WEIGHT_UNIT
      }
    ],

    // Images + ALT TEXT
    images: extractImages(
      data,
      CONFIG.IMAGE_KEYS
    )
  };
};


// ============================================
// MAIN PROCESSING
// ============================================

// Step 1
const categorized = items
  .map(item => {

    const data = item.json ?? {};
    const operation = getOperationType(data);

    return { data, operation };

  })
  .filter(({ operation }) => operation !== null);


// Step 2
const createItems =
  categorized.filter(
    ({ operation }) => operation === 'create'
  );

const updateItems =
  categorized.filter(
    ({ operation }) => operation === 'update'
  );

const mark_false =
  categorized.filter(
    ({ operation }) => operation === 'mark false'
  );


// Step 3
const limitedCreateItems =
  createItems.slice(0, CONFIG.MAX_CREATE_ITEMS);


// Step 4
const selectedItems = [
  ...limitedCreateItems,
  ...updateItems,
  ...mark_false
];


// Step 5
const outputItems = selectedItems.map(
  ({ data, operation }) => ({

    json: {

      collection_id1: String(data.Collection_ID1 ?? '').trim(),

      collection_id2: String(data.Collection_ID2 ?? '').trim(),

      collection_id3: String(data.Collection_ID3 ?? '').trim(),

      collection_id4: String(data.Collection_ID4 ?? '').trim(),

      operation,

      product: buildProduct(
        data,
        operation
      )
    }
  })
);


return outputItems.length > 0
  ? outputItems
  : [
      {
        json: {
          sheet_name: CONFIG.SHEET_NAME,
          operation: 'None'
        }
      }
    ];

const sheetName = $input.first()?.json?.__sheet_name
  ?? $('🔄 Loop Through Sheets').item?.json?.sheet_name
  ?? $('🔄 Loop Through Sheets').first()?.json?.sheet_name;
const rows = $input.all().map(i => i.json);

// A product can be created on Shopify but fail to become published to the
// Online Store channel (e.g. an earlier step in the same run threw before the
// publish step ran, or the publish call itself failed transiently). Only
// recently-created rows are checked -- older products have had plenty of
// chances to be caught already, and re-checking the whole historical catalog
// every day would be a lot of wasted API calls for no benefit.
const RECENT_DAYS = 3;
const cutoff = Date.now() - RECENT_DAYS * 24 * 60 * 60 * 1000;

const extractProductId = (url) => String(url || '').match(/\/products\/(\d+)/)?.[1] ?? '';

const out = [];
for (const row of rows) {
  const adminUrl = String(row['Shopify_Update_product_URL'] || '').trim();
  const createTime = String(row['create_time'] || '').trim();
  if (!adminUrl || !createTime) continue;

  const created = Date.parse(createTime);
  if (!Number.isFinite(created) || created < cutoff) continue;

  const productId = extractProductId(adminUrl);
  if (!productId) continue;

  out.push({ json: { product_id: productId, row_number: row.row_number, sheet_name: sheetName } });
}
return out.length ? out : [{ json: { _noneToCheck: true } }];

const GOOGLE_SHEETS = [
'2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration', 'Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab', 'Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround',
// 'Test data'  // Uncomment for testing
];

return GOOGLE_SHEETS
  .filter(Boolean)  // Remove any empty/null values
  .map(sheet_name => ({ json: { sheet_name } }));

// Non-fatal by design -- this is the reconciliation pass itself; a failure
// here just means it gets retried on the next scheduled run's check.
return $input.all().map(item => {
  const res = item.json;
  const errors = res?.errors;
  const userErrors = res?.data?.publishablePublish?.userErrors;
  if (errors?.length || userErrors?.length) {
    return { json: { published: false, publish_error: JSON.stringify(errors?.length ? errors : userErrors) } };
  }
  return { json: { published: true } };
});

// The previous stage's output is not what the next stage needs -- re-emit this sheet's rows (built
// by "🧱 Build Slim Rows", whose latest run is the sheet being processed right now, because the
// loop only moves on after the whole line below has finished).
return $('🧱 Build Slim Rows').all().map(item => ({
  json: item.json,
  pairedItem: { item: 0 }
}));

// Memory fix: the pipeline used to read EVERY column of EVERY row of every sheet (long descriptions, HTML
// signatures, Etsy text...) and keep it in memory for the whole run. Now each sheet is read in two phases:
//   1) only the few short columns the CAD sync / publish check / readiness check need, for all rows
//   2) every column, but only for the rows that are Ready_to_post
// This node turns the header row (row 2) into the column ranges for phase 1.
const DOC = '1ITSJNL7iql08AklUOLI1QSpOO0HlYEb8Dui0eNBXSeI';
const SHEET = $('🔄 Loop Through Sheets').item?.json?.sheet_name
  ?? $('🔄 Loop Through Sheets').first()?.json?.sheet_name;
const headers = ($input.first().json.values?.[0] || []).map(h => String(h ?? '').trim());
const NEEDED = ['Ready_to_post', 'Fields_to_update', 'Shopify_Product_URL', 'Shopify_Update_product_URL',
  'create_time', 'CAD Drawing URL', 'IMAGE URL11'];
const letters = (n) => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
// last occurrence wins, like the Sheets node when a header name repeats
const slimCols = NEEDED.map(name => ({ name, idx: headers.lastIndexOf(name) })).filter(c => c.idx >= 0);
const ranges = slimCols.length
  ? slimCols.map(c => `${q(SHEET)}!${letters(c.idx)}3:${letters(c.idx)}`)
  : [`${q(SHEET)}!A2:A2`];
const slimUrl = `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=COLUMNS&valueRenderOption=FORMATTED_VALUE&`
  + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
return [{ json: { sheet_name: SHEET, headers, lastCol: letters(Math.max(headers.length - 1, 0)), slimCols, slimUrl } }];

// Slim rows for the whole sheet (only the columns planned above), tagged with the sheet they belong to.
// Rows whose slim columns are all empty cannot matter to any stage, so they are dropped. Always emits at
// least one item so the line below keeps running for a sheet with nothing to look at.
const plan = $('🧮 Plan Slim Columns').first().json;
const valueRanges = $input.first().json.valueRanges || [];
const cols = plan.slimCols.map((c, i) => ({ name: c.name, values: valueRanges[i]?.values?.[0] || [] }));
const nRows = cols.reduce((m, c) => Math.max(m, c.values.length), 0);
const out = [];
for (let i = 0; i < nRows; i++) {
  const row = {};
  let any = false;
  for (const c of cols) {
    const v = c.values[i];
    const s = v === undefined || v === null ? '' : String(v);
    row[c.name] = s;
    if (s.trim() !== '') any = true;
  }
  if (any) out.push({ json: { row_number: i + 3, ...row, __sheet_name: plan.sheet_name }, pairedItem: { item: 0 } });
}
return out.length ? out : [{ json: { __sheet_name: plan.sheet_name, __no_rows: true }, pairedItem: { item: 0 } }];

// Phase 2: which rows of this sheet are Ready_to_post? Only those are read in full.
// Consecutive row numbers are merged into one range, and the ranges are sent in chunks of 40.
const DOC = '1ITSJNL7iql08AklUOLI1QSpOO0HlYEb8Dui0eNBXSeI';
const plan = $('🧮 Plan Slim Columns').first().json;
const slim = $('🧱 Build Slim Rows').all().map(i => i.json);
const isReady = (r) => ['yes', 'true'].includes(String(r.Ready_to_post ?? '').trim().toLowerCase());
const rowNumbers = slim.filter(r => r.row_number && isReady(r)).map(r => r.row_number).sort((a, b) => a - b);
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const runs = [];
for (const n of rowNumbers) {
  const last = runs[runs.length - 1];
  if (last && n === last[1] + 1) last[1] = n; else runs.push([n, n]);
}
const ranges = runs.map(([a, b]) => `${q(plan.sheet_name)}!A${a}:${plan.lastCol}${b}`);
if (!ranges.length) {
  // nothing ready: a harmless request (the header row) so the line still continues
  return [{ json: { noReady: true, url: `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values/${encodeURIComponent(q(plan.sheet_name) + '!2:2')}` } }];
}
const out = [];
for (let i = 0; i < ranges.length; i += 40) {
  const chunk = ranges.slice(i, i + 40);
  out.push({ json: { noReady: false, url: `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=ROWS&valueRenderOption=FORMATTED_VALUE&` + chunk.map(r => 'ranges=' + encodeURIComponent(r)).join('&') } });
}
return out;

// Turns the full-row responses into the same row objects the "Read Sheet Data" node used to produce
// (header name -> cell text, plus row_number), but only for the Ready_to_post rows. These go straight into
// the unchanged product filter. A sheet with nothing ready emits one not-ready placeholder.
const plan = $('🧮 Plan Slim Columns').first().json;
if ($('🔎 Pick Ready Rows').all()[0]?.json?.noReady) {
  return [{ json: { __sheet_name: plan.sheet_name, __no_ready: true } }];
}
const out = [];
for (const resp of $input.all()) {
  for (const vr of (resp.json.valueRanges || [])) {
    const m = String(vr.range || '').match(/!\$?[A-Z]+(\d+)/);
    const start = m ? Number(m[1]) : null;
    (vr.values || []).forEach((vals, k) => {
      const row = {};
      plan.headers.forEach((h, i) => { if (h) row[h] = vals[i] === undefined ? '' : vals[i]; });
      row.row_number = start + k;
      row.__sheet_name = plan.sheet_name;
      out.push({ json: row });
    });
  }
}
return out.length ? out : [{ json: { __sheet_name: plan.sheet_name, __no_ready: true } }];
